const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const pages=$$("article"),links=$$(".sidebar nav a"),side=$("#side"),finder=$("#finder"),query=$("#query"),results=$("#results");function route(){let id=location.hash.slice(1)||"overview";if(!$("#"+id))id="overview";pages.forEach(p=>p.classList.toggle("active",p.id===id));links.forEach(a=>a.classList.toggle("active",a.hash==="#"+id));$("#crumb").textContent="Portfolio / "+$("#"+id).dataset.title;side.classList.remove("open");scrollTo(0,0);document.title=$("#"+id).dataset.title+" | Ranjeet Gupta"}addEventListener("hashchange",route);route();function theme(){let d=document.documentElement;d.dataset.theme=d.dataset.theme==="dark"?"light":"dark";localStorage.setItem("rg-theme",d.dataset.theme)}if(localStorage.getItem("rg-theme"))document.documentElement.dataset.theme=localStorage.getItem("rg-theme");$$(".theme").forEach(b=>b.onclick=theme);$("#open").onclick=()=>side.classList.add("open");$("#close").onclick=$("#scrim").onclick=()=>side.classList.remove("open");const items=pages.map(p=>({id:p.id,title:p.dataset.title,text:p.innerText.toLowerCase()}));function showSearch(){finder.showModal();query.value="";render("");setTimeout(()=>query.focus(),20)}function render(q){let m=items.filter(x=>!q||x.text.includes(q.toLowerCase()));results.innerHTML=m.map(x=>`<li><a href="#${x.id}"><b>${x.title}</b><small>Open section →</small></a></li>`).join("")||"<li>No matching section found.</li>";results.querySelectorAll("a").forEach(a=>a.onclick=()=>finder.close())}$("#search").onclick=showSearch;$("#esc").onclick=()=>finder.close();query.oninput=e=>render(e.target.value);addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();showSearch()}if(e.key==="Escape"&&finder.open)finder.close()});addEventListener("scroll",()=>{$(".progress i").style.width=(scrollY/(document.documentElement.scrollHeight-innerHeight)*100||0)+"%"},{passive:true});
